420	// 同一になり、書き込み元は書いたつもりのまま記録上は無い扱いになる (実測:
421	// investigation: だけの記録が検査 0 件でサマリにも出なかった)。
422	// 旧様式の recurrence も同じで、null は「無い」と同一になり、書きかけの項目が消える。
423	// consequence / premise_check の null は必須サブキーの欠落として既に報告されるので
424	// ここに含めない。重ねると 1 つの書き忘れが複数の問題になるため。
425	var recordNullSilentKeys = map[string]bool{"plan_ref": true, "prior_defect": true, "investigation": true, "verification": true, "doc_dag": true, "recurrence": true}
426	
427	// recordUnknownKeyProblems は許可キー集合との突き合わせで未知のキーと、
428	// 値の無い構造キー (recordNullSilentKeys) を列挙する。
429	// 問題が見つかっても走査を続け、他の問題の報告を妨げない。
430	func recordUnknownKeyProblems(f string, n *yaml.Node) []string {
431		var problems []string
432		var walkMap func(n *yaml.Node, kind string)
433		walkSeq := func(n *yaml.Node, kind string) {
434			if n == nil || n.Kind != yaml.SequenceNode {
435				return
436			}
437			for _, item := range n.Content {
438				walkMap(item, kind)
439			}
440		}
441		walkMap = func(n *yaml.Node, kind string) {
442			if n == nil || n.Kind != yaml.MappingNode {
443				return
444			}
445			allowed := recordAllowedKeys[kind]
446			for i := 0; i+1 < len(n.Content); i += 2 {
447				k, v := n.Content[i], n.Content[i+1]
448				if !allowed[k.Value] {
449					problems = append(problems, fmt.Sprintf(
450						"%s:%d: %sに未知のキー %q。旧いキー名の残存か、キーを書く位置のミス (上流固有の属性は attrs へ) を疑う",
451						f, k.Line, kind, k.Value))
452					continue
453				}
454				if recordNullSilentKeys[k.Value] && v.Kind == yaml.ScalarNode && v.Tag == "!!null" {
455					problems = append(problems, fmt.Sprintf(
456						"%s:%d: %s の %s に値がありません。書くなら中身を書き、書かないならキーごと消す (値の無いキーは「無い」と同じに扱われ、書いたつもりの記録が警告なく消える)",
457						f, k.Line, kind, k.Value))
458					continue
459				}
460				switch k.Value {
461				case "runs":
462					walkSeq(v, "実行")
463				case "findings":
464					walkSeq(v, "指摘")
465				case "plans":
466					walkSeq(v, "修正計画")
467				case "consequence":
468					walkMap(v, "帰結")
469				case "premise_check":
470					walkMap(v, "根拠の検証")
471				case "plan_ref":
472					walkMap(v, "束ね先")
473				case "prior_defect":
474					walkMap(v, "前からある欠陥")
475				case "investigation":
476					walkMap(v, "調査")
477				case "verification":
478					walkMap(v, "検証")
479				case "doc_dag":
480					walkMap(v, "doc-dag の確認")
481				case "recurrence":
482					walkMap(v, "検知")
483				case "evidence":
484					walkSeq(v, "根拠")
485				case "reframe":
486					walkMap(v, "捉え直し")
487				}
488			}
489		}
490		walkMap(n, "トップレベル")
491		return problems
492	}
