494	var recordDateRe = regexp.MustCompile(`^\d{4}-\d{2}-\d{2}$`)
495	
496	// recordAudiences は被害者の列挙 (glossary のロール + 開発者)。設定 (.claude/review-triage.yaml)
497	// の audience と同じ値域。
498	var recordAudiences = map[string]bool{
499		"operator": true, "admin": true, "provider": true, "developer": true,
500	}
