502	// recordSemanticProblems は必須キー・列挙値・参照の整合を検査する。
503	func recordSemanticProblems(f string, doc *recordDoc) []string {
504		var problems []string
505		add := func(format string, args ...any) {
506			problems = append(problems, f+": "+fmt.Sprintf(format, args...))
507		}
508		if len(doc.Runs) == 0 {
509			add("runs がありません (実行が 1 つも無い)")
510		}
511		// 回ごとの問題 id の索引 (plan_ref の解決と被覆の検査に使う)。
512		plansByRun := make([]map[string]bool, len(doc.Runs))
513		for ri, run := range doc.Runs {
514			plansByRun[ri] = map[string]bool{}
515			for _, pl := range run.Plans {
516				plansByRun[ri][pl.ProblemID] = true
517			}
518		}
519		priorDefectFirstRun := recordPriorDefectFirstRun(doc.Runs)
520		for ri, run := range doc.Runs {
521			rn := fmt.Sprintf("runs[%d] (%s %s)", ri, run.Date, run.Skill)
522			if !recordDateRe.MatchString(run.Date) {
523				add("%s: date が YYYY-MM-DD ではありません: %q", rn, run.Date)
524			}
525			if run.Skill == "" {
526				add("%s: skill がありません", rn)
527			}
528			if run.Model == "" {
529				add("%s: model がありません (レビューを実行したモデルを必ず残す)", rn)
530			}
531			if run.Scope != "incremental" && run.Scope != "full" {
532				add("%s: scope は incremental / full のいずれか: %q", rn, run.Scope)
533			}
534			if run.Head == "" {
535				add("%s: head がありません (レビュー時点の短縮 SHA)", rn)
536			}
537	
538			priorDefectRequired := priorDefectFirstRun >= 0 && ri >= priorDefectFirstRun
539			verdictByID := map[int]string{}
540			for fi, fd := range run.Findings {
541				fn := fmt.Sprintf("%s: findings[%d] (id %d)", rn, fi, fd.ID)
542				if fd.ID <= 0 {
543					add("%s: id は正の整数にする", fn)
544				} else if _, dup := verdictByID[fd.ID]; dup {
545					add("%s: id が同じ回の中で重複しています", fn)
546				}
547				verdictByID[fd.ID] = fd.Verdict
548				for _, kv := range []struct{ key, val string }{
549					{"file", fd.File}, {"summary", fd.Summary},
550					{"category", fd.Category}, {"audience", fd.Audience},
551				} {
552					if kv.val == "" {
553						add("%s: %s がありません", fn, kv.key)
554					}
555				}
556				// audience の列挙。列挙外の値をエラーにせずに通すと D7 (被害者の判定) の入力が壊れる。
557				if fd.Audience != "" && !recordAudiences[fd.Audience] {
558					add("%s: audience は operator / admin / provider / developer のいずれか: %q", fn, fd.Audience)
559				}
560				if fd.AudienceInitial != "" && !recordAudiences[fd.AudienceInitial] {
561					add("%s: audience_initial は operator / admin / provider / developer のいずれか: %q", fn, fd.AudienceInitial)
562				}
563				for _, kv := range []struct{ key, val string }{
564					{"condition", fd.Consequence.Condition}, {"who", fd.Consequence.Who},
565					{"what", fd.Consequence.What}, {"detectability", fd.Consequence.Detectability},
566				} {
567					if kv.val == "" {
568						add("%s: consequence.%s がありません (帰結の 4 項目は必須)", fn, kv.key)
569					}
570				}
571				switch fd.PremiseCheck.Stages {
572				case "none", "A", "A+B":
573				default:
574					add("%s: premise_check.stages は none / A / A+B のいずれか: %q", fn, fd.PremiseCheck.Stages)
575				}
576				switch fd.PremiseCheck.Result {
577				case "verified", "wrong", "unverifiable", "skipped":
578				default:
579					add("%s: premise_check.result は verified / wrong / unverifiable / skipped のいずれか: %q",
580						fn, fd.PremiseCheck.Result)
581				}
582				if (fd.PremiseCheck.Stages == "none") != (fd.PremiseCheck.Result == "skipped") {
583					add("%s: stages が none のときだけ result は skipped (stages %q / result %q)",
584						fn, fd.PremiseCheck.Stages, fd.PremiseCheck.Result)
585				}
586				switch fd.Verdict {
587				case "adopted", "held", "rejected":
588				default:
589					add("%s: verdict は adopted / held / rejected のいずれか: %q", fn, fd.Verdict)
590				}
591				if fd.VerdictReason == "" {
592					add("%s: verdict_reason がありません (判定の経路をノード ID で書く)", fn)
593				}
594				// 指摘の出所。省略時は上流のレビュー (review)。residual はループ中に自己採択したもの
595				// (record-schema.md「ループ中に記録の外で直さない」)。
596				switch fd.Origin {
597				case "", "review", "residual":
598				default:
599					add("%s: origin は review / residual のいずれか (省略時は review): %q", fn, fd.Origin)
600				}
601				for _, m := range recordPriorDefectProblems(priorDefectRequired, fd) {
602					add("%s: %s", fn, m)
603				}
604				if fd.PlanRef != nil {
605					if fd.PlanRef.Run < 1 || fd.PlanRef.Run > len(doc.Runs) {
606						add("%s: plan_ref の run %d は存在しません (回は 1〜%d)", fn, fd.PlanRef.Run, len(doc.Runs))
607					} else if !plansByRun[fd.PlanRef.Run-1][fd.PlanRef.Problem] {
608						add("%s: plan_ref の問題 %q は %d 回目の plans にありません", fn, fd.PlanRef.Problem, fd.PlanRef.Run)
609					}
610				}
611			}
612	
613			problemIDs := map[string]bool{}
614			for _, pl := range run.Plans {
615				if pl.ProblemID != "" && problemIDs[pl.ProblemID] {
616					add("%s: problem_id %q が重複しています", rn, pl.ProblemID)
617				}
618				problemIDs[pl.ProblemID] = true
619			}
620			for pi, pl := range run.Plans {
621				pn := fmt.Sprintf("%s: plans[%d] (%s)", rn, pi, pl.ProblemID)
622				for _, kv := range []struct{ key, val string }{
623					{"problem_id", pl.ProblemID}, {"cause", pl.Cause},
624				} {
625					if kv.val == "" {
626						add("%s: %s がありません", pn, kv.key)
627					}
628				}
629				if len(pl.FindingIDs) == 0 {
630					add("%s: finding_ids がありません (1 つ以上)", pn)
631				}
632				for _, id := range pl.FindingIDs {
633					v, ok := verdictByID[id]
634					if !ok {
635						add("%s: finding_ids の %d は同じ回の findings にありません", pn, id)
636					} else if v != "adopted" {
637						add("%s: finding_ids の %d は採択 (adopted) ではありません (verdict %s)。修正計画は採択だけを束ねる", pn, id, v)
638					}
639				}
640				// externalOnly は done-external 専用のキーが空であることを検査する。
641				// スキーマ表が「done-external のときだけ書く」と定める排他で、書かせる
642				// だけで検査しないと、done でコミット済みなのに外部 URL が残る記録が
643				// エラーにならずに通る (sha の排他は前から検査されていた)。列挙外の status では
644				// 呼ばない。default が列挙違反を報告するので、そこへ重ねると 1 つの
645				// 誤字が 2 つの問題になるため。
646				externalOnly := func() {
647					for _, kv := range []struct{ key, val string }{
648						{"applied_external_url", pl.AppliedExternalURL}, {"notes", pl.Notes},
649					} {

780			isLastRun := ri == len(doc.Runs)-1
781			if len(run.Plans) > 0 || !isLastRun {
782				covered := map[int]bool{}
783				for _, pl := range run.Plans {
784					for _, id := range pl.FindingIDs {
785						covered[id] = true
786					}
787				}
788				for _, fd := range run.Findings {
789					if fd.Verdict != "adopted" || covered[fd.ID] {
790						continue
791					}
792					if fd.PlanRef != nil {
793						continue // 参照自体の実在は上の finding ループで検査済み
794					}
795					add("%s: findings id %d: 採択が修正計画に載っていません (自回の plans にも plan_ref にも無い)", rn, fd.ID)
796				}
797			}
798			for _, cycle := range recordDependsOnCycles(run.Plans) {
799				add("%s: depends_on が循環しています (%s)。順序が定まらない。同じ原因の 1 問題に束ねるべきものを分けていないかを疑う",
800					rn, strings.Join(cycle, " → "))
801			}
802		}
803		return problems
804	}
