806	// recordDependsOnCycles は plans の depends_on の循環を検出する。自己参照は
807	// 個別に報告するのでここでは扱わない。同じ循環は 1 度だけ返す。
808	func recordDependsOnCycles(plans []recordPlan) [][]string {
809		deps := make(map[string][]string, len(plans))
810		for _, pl := range plans {
811			for _, d := range pl.DependsOn {
812				if d != pl.ProblemID {
813					deps[pl.ProblemID] = append(deps[pl.ProblemID], d)
814				}
815			}
816		}
817		const (
818			visiting = 1
819			done     = 2
820		)
821		state := map[string]int{}
822		var cycles [][]string
823		var stack []string
824		var visit func(id string)
825		visit = func(id string) {
826			state[id] = visiting
827			stack = append(stack, id)
828			for _, d := range deps[id] {
829				switch state[d] {
830				case 0:
831					visit(d)
832				case visiting:
833					// stack の d 以降が循環。
834					for i, s := range stack {
835						if s == d {
836							cycle := append(append([]string{}, stack[i:]...), d)
837							cycles = append(cycles, cycle)
838							break
839						}
840					}
841				}
842			}
843			stack = stack[:len(stack)-1]
844			state[id] = done
845		}
846		for _, pl := range plans {
847			if state[pl.ProblemID] == 0 {
848				visit(pl.ProblemID)
849			}
850		}
851		return cycles
852	}
