856	// renderReviewTriageSummary は記録 YAML から人が読むサマリ (Markdown) を生成する。
857	// 件数はすべてここで計算し、人が書いた集計をどこからも読まない。
858	func renderReviewTriageSummary(yamlPath string, data []byte) (string, error) {
859		var doc recordDoc
860		if err := yaml.Unmarshal(data, &doc); err != nil {
861			return "", fmt.Errorf("%s: YAML を読めません: %w", yamlPath, err)
862		}
863		return renderReviewTriageSummaryDoc(yamlPath, &doc), nil
864	}
