866	func renderReviewTriageSummaryDoc(yamlPath string, doc *recordDoc) string {
867		base := path.Base(yamlPath)
868		stem := strings.TrimSuffix(base, ".yaml")
869		var b strings.Builder
870		fmt.Fprintf(&b, "<!-- 生成物。手で編集しない。SSOT は %s。`%s` で再生成する。 -->\n\n", base, summaryCommand)
871		fmt.Fprintf(&b, "# %s のトリアージ記録\n\n", stem)
872		fmt.Fprintf(&b, "SSOT は [%s](%s)。読み方と収束の目安は [README](README.md)。\n\n", base, base)
873	
874		b.WriteString("## 推移\n\n")
875		b.WriteString("| 回 | 日付 | スキル | model | scope | 全件 | 採択 | 保留 | 却下 |\n")
876		b.WriteString("| --- | --- | --- | --- | --- | --- | --- | --- | --- |\n")
877		for i, run := range doc.Runs {
878			adopted, held, rejected := 0, 0, 0
879			for _, fd := range run.Findings {
880				switch fd.Verdict {
881				case "adopted":
882					adopted++
883				case "held":
884					held++
885				case "rejected":
886					rejected++
887				}
888			}
889			// 自由文字列の欄 (skill・model など) は recordCell で無害化する。縦棒が
890			// 入ると桁がずれ、偽の数字が集計値の手前に並ぶため (列挙で守られない欄は検査も
891			// 捕まえない)。
892			fmt.Fprintf(&b, "| %d | %s | `%s` | `%s` | %s | %d | %d | %d | %d |\n",
893				i+1, recordCell(run.Date), recordCell(run.Skill), recordCell(run.Model),
894				recordCell(run.Scope), len(run.Findings), adopted, held, rejected)
895		}
896	
897		for i, run := range doc.Runs {
898			// 鮮度の検査は描画結果の全文一致なので、サマリに出す文言を変えると、ディレクトリに残る
899			// 既存のサマリがすべて古いと報告される。0.24.0 で回の書き方を「N 回目」に変えたときは、
900			// 再生成が要ることを README の「生成サマリの書式の変更」に書いた。束ね先・根拠の行・
901			// 出所の文言も同じ。
902			fmt.Fprintf(&b, "\n## %d 回目: %s `%s`", i+1, recordCell(run.Date), recordCell(run.Skill))
903			if run.RunID != "" {
904				fmt.Fprintf(&b, " (%s)", recordCell(run.RunID))
905			}
906			b.WriteString("\n\n")
907			fmt.Fprintf(&b, "- HEAD `%s` / model `%s` / scope %s",
908				recordCell(run.Head), recordCell(run.Model), recordCell(run.Scope))
909			if run.Level != "" {
910				b.WriteString(" / level " + recordCell(run.Level))
911			}
912			b.WriteString("\n\n")
913	
914			b.WriteString("| # | 指摘 | 分類 / 被害者 | 帰結 (条件 / 何が / 気づけるか) | 検証 | ゲート | 判定 |\n")
915			b.WriteString("| --- | --- | --- | --- | --- | --- | --- |\n")
916			for _, fd := range run.Findings {
917				b.WriteString(recordRow(renderFindingCells(fd)))
918			}
919	
920			// 旧様式の検知の項目。既存の生成サマリを書き換えないよう、位置 (修正計画の前)
921			// と文面を変えない。推移の表にも列を足さない。無い回には出さない (検知を
922			// 廃止した後の回は常に無い)。
923			if run.Recurrence != nil {
924				b.WriteString("\n### 検知\n\n")
925				renderRecurrence(&b, run.Recurrence)
926			}
927	
928			if len(run.Plans) > 0 {
929				b.WriteString("\n### 修正計画\n\n")
930				// 最終列の見出しは「証拠」にする。最終列は、コミットの SHA だけでなくリポジトリ外の
931				// 反映先の URL も取るため (renderPlanCells の証拠の欄)。見出しを SHA のままにすると、
932				// done-external の行に出る URL を SHA として読ませることになる。
933				b.WriteString("| 問題 | 原因 | 含む指摘 | 修正方法 | 順 | 状態 | 証拠 (SHA / URL) |\n")
934				b.WriteString("| --- | --- | --- | --- | --- | --- | --- |\n")
935				for _, pl := range run.Plans {
936					b.WriteString(recordRow(renderPlanCells(pl)))
937				}
938				// 調査済み・未立案 (investigated) の注記。調査フェーズの結果だけがあり、修正方法と
939				// 順序をまだ持たない問題が残っている回にだけ、表の下に件数と問題 id を出す。
940				// 無い回には 1 バイトも出さず、推移の表にも列を足さない。鮮度の検査が描画結果の
941				// 全文一致なので、無い記録の出力が変わるとディレクトリの既存サマリがすべて古いと
942				// 報告されるため (旧様式の検知の小節と同じ形)。
943				renderInvestigatedNote(&b, run.Plans)
944				for _, pl := range run.Plans {
945					if pl.Status == "awaiting-human" {
946						fmt.Fprintf(&b, "\n- **%s は選択待ち (人間が選ぶ)**: %s\n", recordCell(pl.ProblemID), recordCell(pl.Options))
947					}
948				}
949				// リポジトリ外への反映は、コミットを辿っても内容を確認できない。
950				// 反映を確認した方法 (notes) を表の外に出して、後から追えるようにする。
951				for _, pl := range run.Plans {
952					if pl.Status == "done-external" && pl.Notes != "" {
953						fmt.Fprintf(&b, "\n- **%s はリポジトリ外へ反映済み**: %s\n", recordCell(pl.ProblemID), recordCell(pl.Notes))
954					}
955				}
956				// 直す前の調査の範囲と結果。次のレビューで同じ種類の指摘が来たとき、前回の
957				// 調査漏れ (範囲の外だった) か新規かを判別する材料なので表の外に出す。
958				// 無い問題は出さない。無いことが「未調査」を表すため。
959				for _, pl := range run.Plans {
960					if pl.Investigation != nil {
961						fmt.Fprintf(&b, "\n- **%s の調査**: %s\n", recordCell(pl.ProblemID), renderInvestigation(pl.Investigation))
962					}
963				}
964			}
965	
966			if run.Notes != "" {
967				b.WriteString("\n### 観察\n\n" + strings.TrimRight(run.Notes, "\n") + "\n")
968			}
969		}
970		return b.String()
971	}
