1	// judgment_flow.go は review-triage の判定フローの SSOT (judgment-flow.md) について、
2	// mermaid の図のノード ID 集合と決定表の ID 集合が 1:1 で一致するかを検査する
3	// (judgment-flow)。
4	//
5	// 図は「ノードと遷移」だけ、表は「各ノードの条件と書くもの」だけを持ち、同じ事実を
6	// 二度語らない。残るずれ方は ID 集合の不一致だけなので、そこを機械で照合する。
7	// 生成はせず、照合だけを行う。
8	package main
9	
10	import (
11		"errors"
12		"fmt"
13		"io/fs"
14		"regexp"
15		"sort"
16		"strings"
17	)
18	
19	// judgmentFlowPath は判定フローの SSOT。ファイルが存在しないときは検査を
20	// 何もしない (対象は git 追跡でなくファイルの実在で決める)。
21	//
22	// スキルがプラグインとして配られると、この SSOT はリポジトリの外 (プラグインの
23	// 展開先) に置かれ、パスは環境ごとに違う。main が CLAUDE_PLUGIN_ROOT または
24	// -judgment-flow から解決して設定する。デフォルトはリポジトリ内にスキルを直接置く
25	// 形 (プラグイン化前の配置) で、そのときだけこの値がそのまま使われる。
26	var judgmentFlowPath = ".claude/skills/review-triage/references/judgment-flow.md"
27	
28	var (
29		// judgmentFlowIDRe はノード ID の形。判定 (D)・評価 (E)・採択 (A)・保留 (H)・却下 (R)。
30		judgmentFlowIDRe = regexp.MustCompile(`\b([ADEHR]\d+)\b`)
31		// judgmentFlowTableRowRe は決定表の行 (先頭セルが ID)。パイプ前後の空白の
32		// 詰め方には依存しない。
33		judgmentFlowTableRowRe = regexp.MustCompile(`^\|\s*([ADEHR]\d+)\s*\|`)
34		// judgmentFlowQuoteRe は mermaid のラベル文字列。ID の抽出前に取り除く
35		// (ラベル内の "D1: ..." のような表示用の ID を数えないため)。
36		judgmentFlowQuoteRe = regexp.MustCompile(`"[^"]*"`)
37		// judgmentFlowColorRe は色コード。`#A12` のような大文字の短い 16 進が
38		// ID の形 ([ADEHR]\d+) に一致してしまうため、抽出前に取り除く (観点 F の反例)。
39		judgmentFlowColorRe = regexp.MustCompile(`#[0-9A-Fa-f]+`)
40		// judgmentFlowSeparatorRe は表の区切り行 (| --- | --- |)。直前の行は見出しで、
41		// 先頭セルが ID の形でも本体行として数えない。
42		judgmentFlowSeparatorRe = regexp.MustCompile(`^\s*\|(\s*:?-{3,}:?\s*\|)+\s*$`)
43	)
44	
45	// judgmentFlowDecorations は ID の出所にしない装飾行の先頭トークン。
46	var judgmentFlowDecorations = map[string]bool{
47		"style": true, "class": true, "classDef": true, "click": true, "linkStyle": true,
48	}
49	
50	// judgmentFlowProblems は図と表の ID 集合を照合する。対象は git 追跡でなく
51	// ファイルの実在で決める。追跡前の判定フローが検査の対象に入らず、0 件マッチのまま
52	// 検査が成功する種類の欠陥 (B1 と同じ) を防ぐため。
53	//
54	// ファイルが無いときの扱いは origin で分かれる。origin はパスを指定したものの
55	// 名前 (-judgment-flow / CLAUDE_PLUGIN_ROOT) で、空なら指定が無い。パスを指定する
56	// ことは「そこを検査せよ」という意思表示なので、不在は問題として報告する。指定が
57	// 無いまま不在なのはスキル未導入の正常な状態で、何もしない。1 つの入口に 2 つの
58	// 意味を担わせると、プラグインがファイルを移動・改名した時点で利用者のリポジトリの検査が
59	// 利用者に知らせずに無効になり、「実行されて合格した」と「そもそも実行されなかった」が区別できなくなる
60	// (rejection-gates.md の「診断ツールの偽陰性」)。
61	//
62	// origin を真偽値でなく名前にするのは、報告を読む人が直す先を特定できるようにする
63	// ためである。解決の経路が 2 つあるので、どちらを直せばよいかが分からないと調べ直しになる。
64	// files は他の検査とシグネチャを揃えるための引数で、使わない。
65	func judgmentFlowProblems(_ []string, readFile func(string) ([]byte, error), origin string) []string {
66		data, err := readFile(judgmentFlowPath)
67		if err != nil {
68			if errors.Is(err, fs.ErrNotExist) {
69				if origin != "" {
70					return []string{fmt.Sprintf(
71						"%s: %s が指す判定フローの SSOT が存在しません (検査が行われないまま成功するため報告する)",
72						judgmentFlowPath, origin)}
73				}
74				return nil
75			}
76			return []string{fmt.Sprintf("%s: 読み込みに失敗しました: %v", judgmentFlowPath, err)}
77		}
78	
79		var problems []string
80		diagramIDs := map[string]bool{}
81		tableIDs := map[string]int{}
82		inMermaid := false
83		hasMermaid := false
84		lines := strings.Split(string(data), "\n")
85		for i, line := range lines {
86			trimmed := strings.TrimSpace(line)
87			switch {
88			case strings.HasPrefix(trimmed, "```mermaid"):
89				inMermaid = true
90				hasMermaid = true
91				continue
92			case strings.HasPrefix(trimmed, "```"):
93				inMermaid = false
94				continue
95			}
96			if inMermaid {
97				// コメント行 (%%。ディレクティブ %%{...}%% を含む) は ID の出所にしない。
98				if strings.HasPrefix(trimmed, "%%") {
99					continue
100				}
101				// 装飾の行も ID の出所にしない。ノードを消して style 行を消し忘れた
102				// 編集ミスを、ID 照合が「図にある」と誤認しないため。先頭トークンは
103				// strings.Fields で取り出す (タブ区切りも区切りとして扱う)。
104				if fields := strings.Fields(trimmed); len(fields) > 0 && judgmentFlowDecorations[fields[0]] {
105					continue
106				}
107				stripped := judgmentFlowQuoteRe.ReplaceAllString(line, "")
108				stripped = judgmentFlowColorRe.ReplaceAllString(stripped, "")
109				for _, m := range judgmentFlowIDRe.FindAllStringSubmatch(stripped, -1) {
110					diagramIDs[m[1]] = true
111				}
112				continue
113			}
114			if m := judgmentFlowTableRowRe.FindStringSubmatch(line); m != nil {
115				// 直後が区切り行なら、この行は見出しなので、本体行として数えない。
116				if i+1 < len(lines) && judgmentFlowSeparatorRe.MatchString(lines[i+1]) {
117					continue
118				}
119				tableIDs[m[1]]++
120			}
121		}
122	
123		if !hasMermaid {
124			problems = append(problems, fmt.Sprintf("%s: mermaid の図が見つかりません (図がノードと遷移の SSOT)", judgmentFlowPath))
125		}
126		if len(tableIDs) == 0 {
127			problems = append(problems, fmt.Sprintf("%s: 決定表 (先頭セルが ID の行) が見つかりません", judgmentFlowPath))
128		}
129		if !hasMermaid || len(tableIDs) == 0 {
130			return problems
131		}
132	
133		for _, id := range sortedMapKeys(diagramIDs) {
134			if tableIDs[id] == 0 {
135				problems = append(problems, fmt.Sprintf(
136					"%s: %s は図にあるが決定表にありません (条件と書くものを表に足す)", judgmentFlowPath, id))
137			}
138		}
139		for id, n := range tableIDs {
140			if !diagramIDs[id] {
141				problems = append(problems, fmt.Sprintf(
142					"%s: %s は決定表にあるが図にありません (遷移を図に足すか行を消す)", judgmentFlowPath, id))
143			}
144			if n > 1 {
145				problems = append(problems, fmt.Sprintf(
146					"%s: %s の行が決定表で重複しています", judgmentFlowPath, id))
147			}
148		}
149		sort.Strings(problems)
150		return problems
151	}
152	
153	// sortedMapKeys はマップのキーを昇順で返す。出力の順序を入力の反復順に
154	// 依存させないため (問題の順序が実行ごとに変わると差分が読めない)。
155	func sortedMapKeys[V any](m map[string]V) []string {
156		keys := make([]string, 0, len(m))
157		for k := range m {
158			keys = append(keys, k)
159		}
160		sort.Strings(keys)
161		return keys
162	}
